#!/usr/bin/env python3
import os, sys, struct, math, errno

VERSION = "0.1.10"
USAGE = "Usage: elfcat <filename>\nWrites <filename>.html to CWD.\n"

E_TYPE = {
    0: "None (NONE)", 1: "Relocatable object file (REL)", 2: "Executable file (EXEC)",
    3: "Shared object file (DYN)", 4: "Core file (CORE)",
}
MACHINE = {
    0: "None", 2: "SPARC", 3: "x86", 8: "MIPS", 20: "PowerPC", 40: "ARM Aarch32",
    50: "Itanium IA-64", 62: "x86-64", 183: "ARM Aarch64", 243: "RISC-V",
}
ABI = {0:"SysV",1:"HP-UX",2:"NetBSD",3:"Linux",6:"Solaris",9:"FreeBSD",12:"OpenBSD",255:"Standalone"}
P_TYPE = {
    0:"NULL",1:"LOAD",2:"DYNAMIC",3:"INTERP",4:"NOTE",5:"SHLIB",6:"PHDR",7:"TLS",
    0x6474e550:"GNU_EH_FRAME (OS-specific)",0x6474e551:"GNU_STACK (OS-specific)",0x6474e552:"GNU_RELRO (OS-specific)",
}
S_TYPE = {
    0:"NULL",1:"PROGBITS",2:"SYMTAB",3:"STRTAB",4:"RELA",5:"HASH",6:"DYNAMIC",7:"NOTE",8:"NOBITS",9:"REL",10:"SHLIB",11:"DYNSYM",
    14:"INIT_ARRAY",15:"FINI_ARRAY",16:"PREINIT_ARRAY",17:"GROUP",18:"SYMTAB_SHNDX",
    0x6ffffff6:"GNU_HASH (OS-specific)",0x6ffffffd:"VER_DEF (OS-specific)",0x6ffffffe:"VER_NEED (OS-specific)",0x6fffffff:"HIOS",
}

class ElfError(Exception): pass

def hx(n): return format(n, 'x')
def h0(n): return '0x' + format(n, 'x')

def human(n):
    units=["B","KiB","MiB","GiB","TiB"]
    if n < 1024:
        return f"{n} B"
    v=float(n); idx=0
    while v >= 1024 and idx < len(units)-1:
        v/=1024.0; idx += 1
    return f"{v:.1f} {units[idx]} ({n} B)"

def compact_human(n):
    if n < 1024: return str(n)
    units=["KiB","MiB","GiB","TiB"]
    v=float(n); idx=-1
    while v >= 1024 and idx < len(units)-1:
        v/=1024.0; idx += 1
    return f"{n} ({v:.1f} {units[idx]})"

def num_hex_dec(n):
    return f"<span class='number' title='{n}'>{h0(n)}</span>"

def num_dec_hex_title(n):
    return f"<span class='number' title='{h0(n)}'>{compact_human(n)}</span>"

def raw_bytes(bs):
    return ' '.join(f'{b:02x}' for b in bs)

def esc_ascii_byte(b):
    if b < 32 or b >= 127:
        return '.'
    c=chr(b)
    if c=='&': return '&amp;'
    if c=='<': return '&lt;'
    if c=='>': return '&gt;'
    if c=='"': return '&quot;'
    if c=="'": return '&apos;'
    return c

def html_ascii(data):
    lines=[]
    for i in range(0,len(data),16):
        lines.append(''.join(esc_ascii_byte(b) for b in data[i:i+16]))
    return '\n'.join(lines)

def read_cstr(blob, off):
    if off < 0 or off >= len(blob): return ""
    end=blob.find(b'\0', off)
    if end < 0: end=len(blob)
    return blob[off:end].decode('utf-8','replace')

def read_strtab_entries(blob):
    out=[]; i=0
    while i < len(blob):
        j=blob.find(b'\0', i)
        if j < 0: j=len(blob)
        if j > i:
            out.append(blob[i:j].decode('utf-8','replace'))
        i=j+1
    return out

class ELF:
    def __init__(self, data):
        self.data=data
        self.parse()
    def unpack(self, fmt, off):
        return struct.unpack_from(self.endian+fmt, self.data, off)
    def parse(self):
        d=self.data
        if len(d)<16: raise ElfError("file is smaller than ELF header's e_ident")
        if d[:4] != b'\x7fELF': raise ElfError("mismatched magic: not an ELF file")
        self.cls=d[4]
        if self.cls not in (1,2): raise ElfError(f"Unknown bitness: {self.cls}")
        self.dataenc=d[5]
        if self.dataenc not in (1,2): raise ElfError(f"Unknown endianness: {self.dataenc}")
        self.endian='<' if self.dataenc==1 else '>'
        self.is64=self.cls==2
        need=64 if self.is64 else 52
        if len(d)<need: raise ElfError("file is smaller than ELF file header")
        if self.is64:
            vals=self.unpack('HHIQQQIHHHHHH',16)
            (self.e_type,self.e_machine,self.e_version,self.e_entry,self.e_phoff,self.e_shoff,self.e_flags,self.e_ehsize,self.e_phentsize,self.e_phnum,self.e_shentsize,self.e_shnum,self.e_shstrndx)=vals
            self.ehdr_size=64
        else:
            vals=self.unpack('HHIIIIIHHHHHH',16)
            (self.e_type,self.e_machine,self.e_version,self.e_entry,self.e_phoff,self.e_shoff,self.e_flags,self.e_ehsize,self.e_phentsize,self.e_phnum,self.e_shentsize,self.e_shnum,self.e_shstrndx)=vals
            self.ehdr_size=52
        self.phdrs=[]
        for i in range(self.e_phnum):
            off=self.e_phoff+i*self.e_phentsize
            if self.is64:
                p_type,p_flags,p_offset,p_vaddr,p_paddr,p_filesz,p_memsz,p_align=self.unpack('IIQQQQQQ',off)
            else:
                p_type,p_offset,p_vaddr,p_paddr,p_filesz,p_memsz,p_flags,p_align=self.unpack('IIIIIIII',off)
            self.phdrs.append(dict(index=i,off=off,p_type=p_type,p_flags=p_flags,p_offset=p_offset,p_vaddr=p_vaddr,p_paddr=p_paddr,p_filesz=p_filesz,p_memsz=p_memsz,p_align=p_align))
        self.shdrs=[]
        for i in range(self.e_shnum):
            off=self.e_shoff+i*self.e_shentsize
            if self.is64:
                sh_name,sh_type,sh_flags,sh_addr,sh_offset,sh_size,sh_link,sh_info,sh_addralign,sh_entsize=self.unpack('IIQQQQIIQQ',off)
            else:
                sh_name,sh_type,sh_flags,sh_addr,sh_offset,sh_size,sh_link,sh_info,sh_addralign,sh_entsize=self.unpack('IIIIIIIIII',off)
            self.shdrs.append(dict(index=i,off=off,sh_name=sh_name,sh_type=sh_type,sh_flags=sh_flags,sh_addr=sh_addr,sh_offset=sh_offset,sh_size=sh_size,sh_link=sh_link,sh_info=sh_info,sh_addralign=sh_addralign,sh_entsize=sh_entsize,name=""))
        if 0 <= self.e_shstrndx < len(self.shdrs):
            sh=self.shdrs[self.e_shstrndx]
            blob=d[sh['sh_offset']:sh['sh_offset']+sh['sh_size']]
            for s in self.shdrs:
                s['name']=read_cstr(blob, s['sh_name'])

def etype_name(v):
    if v in E_TYPE: return E_TYPE[v]
    if 0xfe00 <= v <= 0xfeff: return "Environment-specific use"
    if 0xff00 <= v <= 0xffff: return "Processor-specific use"
    return f"Unknown {v}"

def ptype_name(v):
    return P_TYPE.get(v, f"Unknown: {v}")

def stype_name(v):
    if v in S_TYPE: return S_TYPE[v]
    if 0x60000000 <= v <= 0x6fffffff: return f"Unknown OS-specific: {v}"
    if 0x70000000 <= v <= 0x7fffffff: return f"Unknown processor-specific: {v}"
    return f"Unknown: {v}"

def ph_flags(v):
    s=''
    if v & 4: s+='R'
    if v & 2: s+='W'
    if v & 1: s+='X'
    return s or '0'

def sh_flags(v):
    order=[(1,'W'),(2,'A'),(4,'X'),(0x10,'M'),(0x20,'S'),(0x40,'I'),(0x80,'L'),(0x100,'O'),(0x200,'G'),(0x400,'T'),(0x800,'C'),(0x1000,'x'),(0x2000,'o'),(0x4000,'E')]
    s=''.join(ch for bit,ch in order if v & bit)
    return s or '0'

def interval_class(kind, idx=None):
    if kind=='ehdr': return 'ehdr'
    return ''

class Interval:
    def __init__(self,start,end,html,prio,order=0):
        self.start=start; self.end=end; self.html=html; self.prio=prio; self.order=order

def make_intervals(elf):
    ints=[]; order=0
    def add(start,end,cls,prio):
        nonlocal order
        if end<=start or start>=len(elf.data): return
        end=min(end,len(elf.data))
        ints.append(Interval(start,end,f"<span class='{cls}'>",prio,order)); order+=1
    # ELF header and fields
    ehend=min(elf.ehdr_size, len(elf.data))
    add(0, ehend, 'ehdr', 10)
    add(0,16,'ident',20)
    fields=[(0,4,'magic'),(4,5,'class'),(5,6,'data'),(6,7,'ver'),(7,8,'abi'),(8,9,'abi_ver'),(9,16,'pad')]
    if elf.is64:
        fields += [(16,18,'e_type'),(18,20,'e_machine'),(20,24,'e_version'),(24,32,'e_entry'),(32,40,'e_phoff'),(40,48,'e_shoff'),(48,52,'e_flags'),(52,54,'e_ehsize'),(54,56,'e_phentsize'),(56,58,'e_phnum'),(58,60,'e_shentsize'),(60,62,'e_shnum'),(62,64,'e_shstrndx')]
        phfields=[(0,4,'p_type'),(4,8,'p_flags'),(8,16,'p_offset'),(16,24,'p_vaddr'),(24,32,'p_paddr'),(32,40,'p_filesz'),(40,48,'p_memsz'),(48,56,'p_align')]
        shfields=[(0,4,'sh_name'),(4,8,'sh_type'),(8,16,'sh_flags'),(16,24,'sh_addr'),(24,32,'sh_offset'),(32,40,'sh_size'),(40,44,'sh_link'),(44,48,'sh_info'),(48,56,'sh_addralign'),(56,64,'sh_entsize')]
    else:
        fields += [(16,18,'e_type'),(18,20,'e_machine'),(20,24,'e_version'),(24,28,'e_entry'),(28,32,'e_phoff'),(32,36,'e_shoff'),(36,40,'e_flags'),(40,42,'e_ehsize'),(42,44,'e_phentsize'),(44,46,'e_phnum'),(46,48,'e_shentsize'),(48,50,'e_shnum'),(50,52,'e_shstrndx')]
        phfields=[(0,4,'p_type'),(4,8,'p_offset'),(8,12,'p_vaddr'),(12,16,'p_paddr'),(16,20,'p_filesz'),(20,24,'p_memsz'),(24,28,'p_flags'),(28,32,'p_align')]
        shfields=[(0,4,'sh_name'),(4,8,'sh_type'),(8,12,'sh_flags'),(12,16,'sh_addr'),(16,20,'sh_offset'),(20,24,'sh_size'),(24,28,'sh_link'),(28,32,'sh_info'),(32,36,'sh_addralign'),(36,40,'sh_entsize')]
    for a,b,c in fields: add(a,b,c,30)
    # outer regions. skip file-start load-like regions to mimic the original's uncluttered first page.
    for p in elf.phdrs:
        if p['p_filesz']>0 and p['p_offset']>0:
            add(p['p_offset'], p['p_offset']+p['p_filesz'], f"bin_segment{p['index']} segment", 5)
    for s in elf.shdrs:
        if s['sh_size']>0 and s['sh_type']!=8 and s['sh_offset']>0:
            add(s['sh_offset'], s['sh_offset']+s['sh_size'], f"bin_section{s['index']} section hover", 15)
    for p in elf.phdrs:
        add(p['off'], p['off']+elf.e_phentsize, f"bin_phdr{p['index']} phdr", 12)
        for a,b,c in phfields: add(p['off']+a, p['off']+b, c, 30)
    for s in elf.shdrs:
        add(s['off'], s['off']+elf.e_shentsize, f"bin_shdr{s['index']} shdr", 12)
        for a,b,c in shfields: add(s['off']+a, s['off']+b, c, 30)
    return ints

def bytes_div(elf):
    data=elf.data; ints=make_intervals(elf)
    starts={}; ends={}
    for iv in ints:
        starts.setdefault(iv.start,[]).append(iv)
        ends.setdefault(iv.end,[]).append(iv)
    for k in starts: starts[k].sort(key=lambda iv:(iv.prio,iv.order))
    for k in ends: ends[k].sort(key=lambda iv:(-iv.prio,-iv.order))
    out=[]
    for i,b in enumerate(data):
        if i in ends:
            for iv in ends[i]: out.append('</span>')
        if i and i%16==0:
            out.append('\n')
        elif i:
            out.append(' ')
        if i in starts:
            for iv in starts[i]: out.append(iv.html)
        if i in (1,2,3) and data[:4]==b'\x7fELF':
            # not used; keep simple below
            pass
        if i>=0 and i<4 and data[:4]==b'\x7fELF':
            if i==0: out.append('7f')
            elif i==1: out.append('&nbsp;E')
            elif i==2: out.append('&nbsp;L')
            elif i==3: out.append('&nbsp;F')
        else:
            out.append(f'{b:02x}')
    L=len(data)
    if L in ends:
        for iv in ends[L]: out.append('</span>')
    # close any clipped intervals ending at EOF
    open_at_eof=[iv for iv in ints if iv.end==L and L not in ends]
    for iv in sorted(open_at_eof,key=lambda iv:(-iv.prio,-iv.order)): out.append('</span>')
    return ''.join(out)

def note_rows(blob, endian):
    out=[]; off=0; pref='<' if endian=='<' else '>'
    while off+12 <= len(blob):
        namesz,descsz,ntype=struct.unpack_from(pref+'III',blob,off); off+=12
        if namesz==0 and descsz==0: break
        if off+namesz > len(blob): break
        name=blob[off:off+namesz]
        off += ((namesz+3)//4)*4
        if off+descsz > len(blob): break
        desc=blob[off:off+descsz]
        off += ((descsz+3)//4)*4
        if name.endswith(b'\0'): name=name[:-1]
        out.append("            <tr><td><br></td></tr>")
        out.append(f"            <tr> <td>Name:</td> <td>{name.decode('utf-8','replace')}</td> </tr>")
        out.append(f"            <tr> <td>Type:</td> <td>{h0(ntype)}</td> </tr>")
        if name == b'GNU' and ntype == 3 and descsz == 20:
            out.append(f"            <tr> <td>Build ID:</td> <td>{desc.hex()}</td> </tr>")
        else:
            descs=' '.join(f"<b>{b:02x}</b>" for b in desc)
            if descs: descs += ' '
            out.append(f"            <tr> <td>Desc:</td> <td>{descs}</td> </tr>")
    return out

def info_tables(elf):
    lines=[]
    lines.append("    <table id='sticky_table' cellspacing='0'>")
    lines.append("      <tr>")
    lines.append("        <td id='desc'></td>")
    lines.append("        <td class='infotables'>")
    for p in elf.phdrs:
        i=p['index']; lines.append(f"          <table class='conceal itable' id='info_phdr{i}'>")
        lines.append("          <th colspan='2' class='phdr_itable'></th>")
        lines.append(f"            <tr> <td>Type:</td> <td>{ptype_name(p['p_type'])}</td> </tr>")
        lines.append(f"            <tr> <td>Flags:</td> <td>{ph_flags(p['p_flags'])}</td> </tr>")
        lines.append(f"            <tr> <td>Offset in file:</td> <td>{num_hex_dec(p['p_offset'])}</td> </tr>")
        lines.append(f"            <tr> <td>Size in file:</td> <td>{num_dec_hex_title(p['p_filesz'])}</td> </tr>")
        lines.append(f"            <tr> <td>Vaddr in memory:</td> <td>{num_hex_dec(p['p_vaddr'])}</td> </tr>")
        lines.append(f"            <tr> <td>Size in memory:</td> <td>{num_dec_hex_title(p['p_memsz'])}</td> </tr>")
        lines.append(f"            <tr> <td>Alignment:</td> <td>{num_hex_dec(p['p_align'])}</td> </tr>")
        lines.append("          </table>")
    for s in elf.shdrs:
        i=s['index']; lines.append(f"          <table class='conceal itable' id='info_shdr{i}'>")
        lines.append("          <th colspan='2' class='shdr_itable'></th>")
        lines.append(f"            <tr> <td>Index:</td> <td>{i}</td> </tr>")
        lines.append(f"            <tr> <td>Name:</td> <td>{s.get('name','')}</td> </tr>")
        lines.append(f"            <tr> <td>Type:</td> <td>{stype_name(s['sh_type'])}</td> </tr>")
        lines.append(f"            <tr> <td>Flags:</td> <td>{sh_flags(s['sh_flags'])}</td> </tr>")
        lines.append(f"            <tr> <td>Vaddr in memory:</td> <td>{num_hex_dec(s['sh_addr'])}</td> </tr>")
        lines.append(f"            <tr> <td>Offset in file:</td> <td>{num_hex_dec(s['sh_offset'])}</td> </tr>")
        lines.append(f"            <tr> <td>Size in file:</td> <td>{num_dec_hex_title(s['sh_size'])}</td> </tr>")
        lines.append(f"            <tr> <td>Linked section:</td> <td>{s['sh_link']}</td> </tr>")
        lines.append(f"            <tr> <td>Extra info:</td> <td>{num_dec_hex_title(s['sh_info'])}</td> </tr>")
        lines.append(f"            <tr> <td>Alignment:</td> <td>{num_hex_dec(s['sh_addralign'])}</td> </tr>")
        lines.append(f"            <tr> <td>Size of entries:</td> <td>{num_dec_hex_title(s['sh_entsize'])}</td> </tr>")
        lines.append("          </table>")
    lines.append("        </td>")
    lines.append("        <td class='infotables'>")
    for p in elf.phdrs:
        i=p['index']; lines.append(f"          <table class='conceal itable' id='info_segment{i}'>")
        lines.append("          <th colspan='2' class='segment_itable'></th>")
        lines.append(f"            <tr> <td>Type:</td> <td>{ptype_name(p['p_type'])}</td> </tr>")
        lines.append(f"            <tr> <td>Size in file:</td> <td>{num_dec_hex_title(p['p_filesz'])}</td> </tr>")
        lines.append(f"            <tr> <td>Size in memory:</td> <td>{num_dec_hex_title(p['p_memsz'])}</td> </tr>")
        if p['p_type']==4 and p['p_filesz']>0:
            blob=elf.data[p['p_offset']:p['p_offset']+p['p_filesz']]
            lines.extend(note_rows(blob, elf.endian))
        lines.append("          </table>")
    for s in elf.shdrs:
        i=s['index']; lines.append(f"          <table class='conceal itable' id='info_section{i}'>")
        lines.append("          <th colspan='2' class='section_itable'></th>")
        lines.append(f"            <tr> <td>Type:</td> <td>{stype_name(s['sh_type'])}</td> </tr>")
        lines.append(f"            <tr> <td>Size:</td> <td>{num_dec_hex_title(s['sh_size'])}</td> </tr>")
        if s['sh_type']==3 and s['sh_size']>0:
            blob=elf.data[s['sh_offset']:s['sh_offset']+s['sh_size']]
            entries=read_strtab_entries(blob)
            if entries:
                lines.append("            <tr><td><br></td></tr>")
                lines.append("            <tr>")
                lines.append("              <td></td>")
                lines.append("              <td>")
                lines.append("                <div>")
                for e in entries:
                    lines.append(f"                  {e}")
                lines.append("                </div>")
                lines.append("              </td>")
                lines.append("            </tr>")
        lines.append("          </table>")
    lines.append("        </td>")
    lines.append("      </tr>")
    lines.append("    </table>")
    return '\n'.join(lines)

