def arrow_script(elf):
    lines=["    <script type='text/javascript'>", f"      let fileLen = {len(elf.data)}", "      function populateOffsets(columns) {", "          let rows = Math.ceil(fileLen / columns);", "          let elements = \"\";", "          let offset = 0;", "", "          for (let i = 0; i < rows; ++i) {", "              elements += offset.toString(16) + \"</br>\\n\";", "              offset += columns;", "          }", "", "          document.getElementById('offsets').innerHTML = elements;", "      }", "    </script>", "    <script type='text/javascript'>", "      const arrows = document.getElementById('arrows');", "      let connections = [];", "      let batchElems = '';", "      function getAbsPosition(elem) { let x = 0, y = 0; do { x += elem.offsetLeft || 0; y += elem.offsetTop || 0; elem = elem.offsetParent; } while (elem); return {x: x, y: y}; }", "      function getBoundingBoxSizes(elem) { let rect = elem.getBoundingClientRect(); return {w: rect.width || elem.offsetWidth, h: rect.height || elem.offsetHeight}; }", "      function addSvgArrow(elem1, elem2) { let off1 = getAbsPosition(elem1); let off2 = getAbsPosition(elem2); let bb1 = getBoundingBoxSizes(elem1); let x1 = off1.x + bb1.w / 2; let y1 = off1.y; let x2 = off2.x; let y2 = off2.y; batchElems += '<line x1="' + x1 + '" y1="' + y1 + '" ' + 'x2="' + x2 + '" y2="' + y2 + '"/>'; }", "      function jumpToElem(elem) { elem.scrollIntoView(); }", "      function setJumpCallback(elemFrom, elemTo) { elemFrom.addEventListener(\"click\", function(e) { jumpToElem(elemTo); }, true); }", "      function connect(sel1, sel2) { let elem1 = document.querySelector(sel1); let elem2 = document.querySelector(sel2); if (elem1 === null || elem2 === null) { return; } connections.push([elem1, elem2]); addSvgArrow(elem1, elem2); setJumpCallback(elem1, elem2); setJumpCallback(elem2, elem1); }", "      function clearArrows() { batchElems = ''; arrows.innerHTML = ''; }", "      function pushArrowElems() { arrows.innerHTML = batchElems; }", "      function redrawArrows() { clearArrows(); for (let i = 0; i < connections.length; ++i) { let conn = connections[i]; addSvgArrow(conn[0], conn[1]); } pushArrowElems(); }", "      window.onresize = function() { redrawArrows(); }", ""]
    if elf.e_phnum:
        lines.append("      connect('.e_phoff', '.bin_phdr0');")
    if elf.e_shnum:
        lines.append("      connect('.e_shoff', '.bin_shdr0');")
    for p in elf.phdrs:
        lines.append(f"      connect('.bin_phdr{p['index']} > .p_offset', '.bin_segment{p['index']}');")
    for s in elf.shdrs:
        lines.append(f"      connect('.bin_shdr{s['index']} > .sh_offset', '.bin_section{s['index']}');")
        if 0 <= s['sh_link'] < len(elf.shdrs) and s['sh_link'] != 0:
            lines.append(f"      connect('.bin_shdr{s['index']} > .sh_link', '.bin_shdr{s['sh_link']}');")
    lines += ["      pushArrowElems();", "    </script>", "    <script type='text/javascript'>", "      const settings = document.getElementById('settings');", "      const help = document.getElementById('help');", "      const arrow_input = document.getElementById('arrow_opacity_range');", "      /* const arrows is reused from arrows.js */", "", "      function toggleVisibility(elem) {", "          if (elem.style.display === \"none\" || elem.style.display === \"\") {", "              elem.style.display = \"block\";", "          } else {", "              elem.style.display = \"none\";", "          }", "      }", "", "      document.getElementById('settings_toggle').onclick = function() {", "          toggleVisibility(settings);", "", "          help.style.display = \"none\";", "      }", "", "      document.getElementById('help_toggle').onclick = function() {", "          toggleVisibility(help);", "", "          settings.style.display = \"none\";", "      }", "", "      function setArrowOpacity(e) {", "          arrows.style.opacity = e.target.valueAsNumber / 100;", "      }", "", "      arrow_input.addEventListener('change', setArrowOpacity);", "      arrow_input.addEventListener('input', setArrowOpacity);", "    </script>", "  </body>", "</html>"]
    return '\n'.join(lines)

def report(path, elf):
    title=os.path.basename(path.rstrip('/')) or os.path.basename(path)
    lines=[HEAD_TMPL.format(title=title)]
    lines.append(f"      <tr class='fileinfo_file_name'> <td>File name:</td> <td>{path}</td> </tr>")
    lines.append(f"      <tr class='fileinfo_file_size'> <td>File size:</td> <td>{human(len(elf.data))}</td> </tr>")
    lines.append(f"      <tr class='fileinfo_class'> <td>Object class:</td> <td>{'64-bit' if elf.is64 else '32-bit'}</td> </tr>")
    lines.append(f"      <tr class='fileinfo_data'> <td>Data encoding:</td> <td>{'Little endian' if elf.dataenc==1 else 'Big endian'}</td> </tr>")
    abi_name=ABI.get(elf.data[7], f"Unknown: {elf.data[7]}")
    if elf.data[7]==0:
        lines.append(f"      <tr class='fileinfo_abi'> <td>ABI:</td> <td>{abi_name}</td> </tr>")
    else:
        lines.append(f"      <tr class='fileinfo_abi'> <td>Uncommon ABI(!):</td> <td>{abi_name}</td> </tr>")
        lines.append(f"      <tr class='fileinfo_abi_ver'> <td>ABI version:</td> <td>{elf.data[8]}</td> </tr>")
    lines.append(f"      <tr class='fileinfo_e_type'> <td>Type:</td> <td>{etype_name(elf.e_type)}</td> </tr>")
    lines.append(f"      <tr class='fileinfo_e_machine'> <td>Architecture:</td> <td>{MACHINE.get(elf.e_machine, 'Unknown: '+str(elf.e_machine))}</td> </tr>")
    lines.append(f"      <tr class='fileinfo_e_entry'> <td>Entrypoint:</td> <td>{num_hex_dec(elf.e_entry)}</td> </tr>")
    lines.append(f"      <tr class='fileinfo_ph'> <td>Program headers:</td> <td><span title='{h0(elf.e_phnum)}' class='number fileinfo_e_phnum'>{elf.e_phnum}</span> * <span title='{h0(elf.e_phentsize)}' class='number fileinfo_e_phentsize'>{elf.e_phentsize}</span> @ <span title='{h0(elf.e_phoff)}' class='number fileinfo_e_phoff'>{elf.e_phoff}</span></td> </tr>")
    lines.append(f"      <tr class='fileinfo_sh'> <td>Section headers:</td> <td><span title='{h0(elf.e_shnum)}' class='number fileinfo_e_shnum'>{elf.e_shnum}</span> * <span title='{h0(elf.e_shentsize)}' class='number fileinfo_e_shentsize'>{elf.e_shentsize}</span> @ <span title='{h0(elf.e_shoff)}' class='number fileinfo_e_shoff'>{elf.e_shoff}</span></td> </tr>")
    lines.append("    </table>")
    offsets='\n'.join(format(i,'x') for i in range(0,len(elf.data),16))
    lines.append(f"    <div id='offsets'>{offsets}</div>")
    lines.append(f"    <div id='bytes'>{bytes_div(elf)}</div>")
    lines.append(f"    <div id='ascii'>{html_ascii(elf.data)}</div>")
    lines.append(info_tables(elf))
    lines.append(TAIL_SCRIPT_1.rstrip('\n'))
    lines.append(arrow_script(elf))
    return '\n'.join(lines) + '\n'

def main(argv):
    if len(argv)==2 and argv[1] in ('-h','--help'):
        sys.stdout.write(USAGE); return 0
    if len(argv)==2 and argv[1]=='--version':
        sys.stdout.write(f"elfcat {VERSION}\n"); return 0
    if len(argv)!=2:
        sys.stdout.write(USAGE); return 1
    path=argv[1]
    try:
        with open(path,'rb') as f: data=f.read()
    except OSError as e:
        sys.stderr.write(f"Failed to read file \"{path}\": {e.strerror} (os error {e.errno})\n")
        return 1
    try:
        elf=ELF(data)
    except ElfError as e:
        sys.stderr.write(f"Failed to parse ELF: {e}\n")
        return 1
    outname=(os.path.basename(path.rstrip('/')) or os.path.basename(path)) + '.html'
    html=report(path, elf)
    try:
        with open(outname,'w',encoding='utf-8') as f: f.write(html)
    except OSError as e:
        sys.stderr.write(f"Failed to write report: {e.strerror} (os error {e.errno})\n")
        return 0
    return 0

if __name__ == '__main__':
    sys.exit(main(sys.argv))
